t.script:
(function () {
    'use strict';

    /* ── helpers ────────────────────────────────────────────────────── */
    function fmt(bytes) {
        if (bytes < 1024) return bytes + ' B';
        if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
        return (bytes / 1048576).toFixed(1) + ' MB';
    }

    function fileIcon(name) {
        var ext = (name.split('.').pop() || '').toLowerCase();
        var map = {
            pdf: 'fa-file-pdf-o',
            doc: 'fa-file-word-o', docx: 'fa-file-word-o',
            xls: 'fa-file-excel-o', xlsx: 'fa-file-excel-o',
            txt: 'fa-file-text-o',
            jpg: 'fa-file-image-o', jpeg: 'fa-file-image-o',
            png: 'fa-file-image-o', gif: 'fa-file-image-o', webp: 'fa-file-image-o'
        };
        return 'fa ' + (map[ext] || 'fa-file-o');
    }

    /* ── Request type cards ──────────────────────────────────────────── */
    var typeCards  = document.querySelectorAll('.hd-type-card');
    var typeHidden = document.getElementById('request_type_hidden');
    var typeError  = document.getElementById('hd-type-error');

    /* ── Attachment becomes mandatory for Technical Issue requests ────── */
    var attachmentStar  = document.getElementById('hd-attachment-star');
    var attachmentHint  = document.getElementById('hd-attachment-hint');
    var attachmentError = document.getElementById('hd-attachment-client-error');

    function updateAttachmentRequirement() {
        var isIssue = typeHidden.value === 'issue';
        if (attachmentStar) attachmentStar.style.display = isIssue ? 'inline' : 'none';
        if (attachmentHint) {
            attachmentHint.textContent = isIssue
                ? '(required for technical issues – max 10 MB)'
                : '(optional – max 10 MB)';
        }
        if (!isIssue && attachmentError) attachmentError.style.display = 'none';
    }

    typeCards.forEach(function (card) {
        card.addEventListener('click', function () {
            typeCards.forEach(function (c) { c.classList.remove('active'); });
            card.classList.add('active');
            typeHidden.value = card.getAttribute('data-value');
            if (typeError) typeError.style.display = 'none';
            updateAttachmentRequirement();
        });
    });

    /* Reflect the server-rendered selection (e.g. form re-shown after a
       validation error elsewhere, with the client's choice preserved). */
    updateAttachmentRequirement();

    /* ── Priority radio labels ───────────────────────────────────────── */
    var priorityLabels = document.querySelectorAll('.hd-priority-card');
    priorityLabels.forEach(function (label) {
        label.addEventListener('click', function () {
            priorityLabels.forEach(function (l) { l.classList.remove('active'); });
            label.classList.add('active');
        });
    });

    /* ── Team / Assigned To foldable picker ──────────────────────────── */
    var teamPicker  = document.getElementById('hd-team-picker');
    var teamTrigger = document.getElementById('hd-team-picker-trigger');
    var teamLabel   = document.getElementById('hd-team-picker-label');
    var teamPanel   = document.getElementById('hd-team-picker-panel');
    var teamHidden  = document.getElementById('requested_employee_id');

    if (teamPicker && teamTrigger && teamPanel && teamHidden) {
        function closeTeamPanel() { teamPicker.classList.remove('open'); }

        /* The panel is position:fixed (viewport-relative) so it can escape
           this field's card, which has overflow:hidden for its rounded
           corners — an absolutely-positioned panel got clipped there since
           this field sits right at that card's bottom edge. Position it
           from the trigger's actual screen location every time it opens. */
        function positionTeamPanel() {
            var rect = teamTrigger.getBoundingClientRect();
            teamPanel.style.left  = rect.left + 'px';
            teamPanel.style.width = rect.width + 'px';
            var spaceBelow = window.innerHeight - rect.bottom;
            if (spaceBelow < 200 && rect.top > spaceBelow) {
                teamPanel.style.top    = 'auto';
                teamPanel.style.bottom = (window.innerHeight - rect.top + 6) + 'px';
            } else {
                teamPanel.style.bottom = 'auto';
                teamPanel.style.top    = (rect.bottom + 6) + 'px';
            }
        }

        teamTrigger.addEventListener('click', function (e) {
            e.stopPropagation();
            var opening = !teamPicker.classList.contains('open');
            teamPicker.classList.toggle('open');
            if (opening) positionTeamPanel();
        });

        /* A fixed-position panel doesn't move with the page, so close it
           on scroll rather than let it visually detach from the field. */
        window.addEventListener('scroll', function () {
            if (teamPicker.classList.contains('open')) closeTeamPanel();
        }, true);
        window.addEventListener('resize', closeTeamPanel);

        /* "No preference" option */
        var noPrefOption = teamPanel.querySelector('.hd-team-option');
        if (noPrefOption) {
            noPrefOption.addEventListener('click', function () {
                teamHidden.value = '';
                teamLabel.textContent = 'No preference — auto-assign';
                teamLabel.classList.add('placeholder');
                teamPanel.querySelectorAll('.hd-team-employee.selected').forEach(function (el) {
                    el.classList.remove('selected');
                });
                closeTeamPanel();
            });
        }

        /* Fold/unfold each team independently */
        teamPanel.querySelectorAll('.hd-team-group-header').forEach(function (header) {
            header.addEventListener('click', function (e) {
                e.stopPropagation();
                header.closest('.hd-team-group').classList.toggle('open');
            });
        });

        /* Pick an employee */
        teamPanel.querySelectorAll('.hd-team-employee').forEach(function (row) {
            row.addEventListener('click', function () {
                teamHidden.value = row.getAttribute('data-value');
                teamLabel.textContent = row.getAttribute('data-name');
                teamLabel.classList.remove('placeholder');
                teamPanel.querySelectorAll('.hd-team-employee.selected').forEach(function (el) {
                    el.classList.remove('selected');
                });
                row.classList.add('selected');
                closeTeamPanel();
            });
        });

        /* Close when clicking anywhere outside the picker */
        document.addEventListener('click', function (e) {
            if (!teamPicker.contains(e.target)) closeTeamPanel();
        });
    }

    /* ── Multiple-file attachment preview ───────────────────────────── */
    var fileInput   = document.getElementById('attachment');
    var dropzone    = document.getElementById('hd-dropzone');
    var idleArea    = document.getElementById('hd-dropzone-idle');
    var previewArea = document.getElementById('hd-file-preview');

    /* DataTransfer keeps track of chosen files so we can remove individually */
    var chosenFiles = new DataTransfer();

    function syncInputFiles() {
        fileInput.files = chosenFiles.files;
    }

    function renderPreviews() {
        previewArea.innerHTML = '';

        if (chosenFiles.files.length === 0) {
            previewArea.style.display = 'none';
            idleArea.style.display   = 'flex';
            dropzone.classList.remove('has-file');
            return;
        }

        idleArea.style.display   = 'none';
        previewArea.style.display = 'block';
        dropzone.classList.add('has-file');

        /* "Add more files" button shown at the top of the preview area */
        var addMoreBtn = document.createElement('div');
        addMoreBtn.className = 'hd-add-more-wrap';
        addMoreBtn.innerHTML = [
            '<button type="button" class="hd-add-more-btn" id="hd-add-more-btn">',
            '  <i class="fa fa-plus-circle me-1"></i> Add another file',
            '</button>',
            '<span class="hd-file-count">' + chosenFiles.files.length + ' file(s) selected</span>'
        ].join('');
        previewArea.appendChild(addMoreBtn);

        document.getElementById('hd-add-more-btn').addEventListener('click', function (e) {
            e.stopPropagation();
            /* Create a temporary hidden input to open browser picker */
            var tmp = document.createElement('input');
            tmp.type = 'file';
            tmp.multiple = true;
            tmp.accept   = fileInput.accept;
            tmp.style.display = 'none';
            document.body.appendChild(tmp);
            tmp.addEventListener('change', function () {
                Array.from(tmp.files).forEach(function (f) {
                    /* Avoid exact duplicates (same name + size) */
                    var dup = false;
                    Array.from(chosenFiles.files).forEach(function (existing) {
                        if (existing.name === f.name && existing.size === f.size) dup = true;
                    });
                    if (!dup) chosenFiles.items.add(f);
                });
                syncInputFiles();
                renderPreviews();
                document.body.removeChild(tmp);
            });
            tmp.click();
        });

        /* One row per file */
        Array.from(chosenFiles.files).forEach(function (file, idx) {
            var row = document.createElement('div');
            row.className = 'hd-file-item';
            row.innerHTML = [
                '<i class="' + fileIcon(file.name) + ' hd-file-icon"></i>',
                '<div class="hd-file-info">',
                '  <span class="hd-file-name">' + file.name + '</span>',
                '  <span class="hd-file-size">' + fmt(file.size) + '</span>',
                '</div>',
                '<button type="button" class="hd-file-remove" data-idx="' + idx + '" title="Remove">',
                '  <i class="fa fa-times"></i>',
                '</button>'
            ].join('');
            previewArea.appendChild(row);
        });

        /* Remove individual file */
        previewArea.querySelectorAll('.hd-file-remove').forEach(function (btn) {
            btn.addEventListener('click', function (e) {
                e.stopPropagation();
                var removeIdx = parseInt(btn.getAttribute('data-idx'), 10);
                var newDT = new DataTransfer();
                Array.from(chosenFiles.files).forEach(function (f, i) {
                    if (i !== removeIdx) newDT.items.add(f);
                });
                chosenFiles = newDT;
                syncInputFiles();
                renderPreviews();
            });
        });
    }

    if (fileInput) {
        fileInput.addEventListener('change', function () {
            Array.from(fileInput.files).forEach(function (f) {
                var dup = false;
                Array.from(chosenFiles.files).forEach(function (existing) {
                    if (existing.name === f.name && existing.size === f.size) dup = true;
                });
                if (!dup) chosenFiles.items.add(f);
            });
            syncInputFiles();
            renderPreviews();
        });

        /* Drag-and-drop */
        dropzone.addEventListener('dragover',  function (e) { e.preventDefault(); dropzone.classList.add('dragover'); });
        dropzone.addEventListener('dragleave', function ()  { dropzone.classList.remove('dragover'); });
        dropzone.addEventListener('drop', function (e) {
            e.preventDefault();
            dropzone.classList.remove('dragover');
            Array.from(e.dataTransfer.files).forEach(function (f) {
                var dup = false;
                Array.from(chosenFiles.files).forEach(function (existing) {
                    if (existing.name === f.name && existing.size === f.size) dup = true;
                });
                if (!dup) chosenFiles.items.add(f);
            });
            syncInputFiles();
            renderPreviews();
        });
    }

    /* ── Character counter ───────────────────────────────────────────── */
    var textarea = document.getElementById('description');
    var counter  = document.getElementById('hd-char-counter');
    if (textarea && counter) {
        function updateCounter() {
            var len = textarea.value.length;
            counter.textContent = len + ' / 2000';
            counter.classList.toggle('warn', len > 1800 && len <= 2000);
            counter.classList.toggle('over', len > 2000);
        }
        textarea.addEventListener('input', updateCounter);
        updateCounter();
    }

    /* ── Submit spinner ──────────────────────────────────────────────── */
    var form      = document.getElementById('hd-portal-form');
    var submitBtn = document.getElementById('hd-submit-btn');
    if (form && submitBtn) {
        form.addEventListener('submit', function (e) {
            /* Technical Issue requires at least one attachment. */
            if (typeHidden.value === 'issue' && chosenFiles.files.length === 0) {
                e.preventDefault();
                if (attachmentError) {
                    attachmentError.style.display = 'flex';
                    attachmentError.scrollIntoView({behavior: 'smooth', block: 'center'});
                }
                return;
            }
            submitBtn.disabled = true;
            submitBtn.innerHTML = '<span class="spinner-border me-2"></span>Submitting…';
        });
    }

    /* ── Prevent bfcache from restoring filled form on back-navigation ── */
    window.addEventListener('pageshow', function (e) {
        if (e.persisted) {
            /* Page was served from the browser's back-forward cache.
               Reload so the server always returns a fresh empty form. */
            window.location.reload();
        }
    });

})();

(function () {
    /* Replace the current history entry so the back button has nowhere to go
       back to within this flow. Any attempt to navigate back just pushes the
       same URL again, keeping the user on this success page. */
    history.replaceState(null, '', location.href);
    history.pushState(null, '', location.href);

    window.addEventListener('popstate', function () {
        history.pushState(null, '', location.href);
    });
})();
